import{dependencies,logging}from"../middlewares/_middlewares.js";import{router as apiRoutes}from"./api/index.js";import{constants}from"../utils/constants/_constants.js";import cors from"cors";import express from"express";const app=express();app.disable("x-powered-by");app.use(express.json());app.use(express.urlencoded({extended:false}));app.use(cors({origin:"*"}));app.use(dependencies);app.use(logging);app.use("/api",apiRoutes);app.get("/",(req,res,next)=>{res.status(200).send(constants.MESSAGE_PAGE_WELCOME)});app.use((req,res,next)=>{res.status(404).send(constants.MESSAGE_PAGE_NOT_FOUND)});export default app;